127|pub fn validate_pin(pin: &ObjectPin) -> Result<()> {
128|    ensure!(pin.filesystem_uuid == HOST_FS || pin.filesystem_uuid == ROOT_FS,
129|        "filesystem not enrolled; recovery excluded");
130|    ensure!(pin.subvolume_id >= 256 && pin.inode > 0, "missing object ID/inode");
131|    ensure!(!uuid::Uuid::parse_str(&pin.subvolume_uuid)?.is_nil(), "nil object UUID");
132|    crate::objects::checked_absolute(&pin.path)?;
133|    Ok(())
