122|/// GET_SUBVOL_INFO returns root-item flags (readonly bit0). btrfs-uapi0.13
123|/// truncates those through its ioctl-flag type (readonly bit1), so its
124|/// SubvolumeInfo.flags cannot establish read-only state. Query GETFLAGS on the
125|/// same already validated descriptor; that ioctl uses the correct bit1 space.
126|pub fn readonly(file: &File) -> Result<bool> {
127|    Ok(btrfs_uapi::subvolume::subvolume_flags_get(file.as_fd())?
128|        .contains(btrfs_uapi::subvolume::SubvolumeFlags::RDONLY))
