66|pub struct Engine<B: Backend, J: Journal> {
67|    policy: Policy,
68|    backend: B,
69|    journal: J,
70|}
71|impl<B: Backend, J: Journal> Engine<B, J> {
72|    pub fn new(policy: Policy, backend: B, journal: J) -> Result<Self> {
73|        policy.validate()?;
74|        Ok(Self { policy, backend, journal })
75|    }
76|    pub fn policy(&self) -> &Policy { &self.policy }
77|
78|    fn state(&mut self) -> Result<State> {
79|        let state = self.journal.load()?;
80|        ensure!(state.version == 1, "uninitialized/unsupported state; explicit operator bootstrap required");
81|        ensure!(state.candidate.is_none() || state.retired.is_none(), "invalid three-set state");
82|        let mut receipts = std::collections::BTreeSet::new();
83|        for set in [&state.retained, &state.candidate, &state.retired].into_iter().flatten() {
84|            let id = uuid::Uuid::parse_str(&set.receipt_id)?;
85|            // Preserve recovery-record provenance without requiring or managing
86|            // application release objects.
87|            ensure!((set.golden_source_uuid.is_empty() && set.golden_received_uuid.is_empty())
88|                || (!uuid::Uuid::parse_str(&set.golden_source_uuid)?.is_nil()
89|                    && !uuid::Uuid::parse_str(&set.golden_received_uuid)?.is_nil()), "invalid legacy golden pair host reference");
90|            ensure!(!id.is_nil() && receipts.insert(&set.receipt_id), "duplicate/invalid receipt");
91|            ensure!(set.entries.len() == self.policy.host_members.len(), "incomplete manifest");
92|            let mut members = std::collections::BTreeSet::new();
93|            for (i, e) in set.entries.iter().enumerate() {
94|                ensure!(e.member == self.policy.host_members[i].member, "state member order mismatch");
95|                ensure!(self.policy.host_members.iter().any(|m| m.member == e.member)
96|                    && members.insert(&e.member), "unknown/duplicate state member");
97|                ensure!(e.name == format!("set-{}", set.receipt_id), "non-owned snapshot name");
98|                ensure!(!e.removed || e.deleting, "invalid removal state");
99|                if let Some(o) = &e.object {
100|                    let p = self.policy.host_members.iter().find(|m| m.member == e.member).unwrap();
101|                    ensure!(o.member == e.member && o.filesystem_uuid == p.source.filesystem_uuid
102|                        && o.parent_uuid == p.source.subvolume_uuid && o.subvolume_id >= 256
103|                        && o.destination == format!("{}/{}", p.destination_parent.path, e.name), "invalid owned object receipt");
104|                    ensure!(!uuid::Uuid::parse_str(&o.subvolume_uuid)?.is_nil(), "invalid snapshot UUID");
105|                }
106|                ensure!(!set.verified || e.object.is_some(), "verified set without object identity");
107|            }
108|        }
109|        Ok(state)
110|    }
111|
112|    fn parents(&mut self, state: &State) -> Result<Vec<B::Handle>> {
113|        let mut parents = Vec::new();
114|        for member in &self.policy.host_members {
115|            let parent = self.backend.open_pin(&member.destination_parent, true)?;
116|            let mut expected = Vec::new();
117|            for set in [&state.retained, &state.candidate, &state.retired].into_iter().flatten() {
118|                let e = set.entries.iter().find(|e| e.member == member.member).context("missing member")?;
119|                if !e.removed { expected.push(e.name.clone()); }
120|            }
121|            let actual = self.backend.names(&parent)?;
122|            // A reserved but not yet created candidate is allowed to be missing.
123|            ensure!(actual.iter().all(|n| expected.contains(n)), "unowned entry/count in snapshot destination");
124|            ensure!(actual.len() <= 2, "snapshot retention count exceeded");
125|            parents.push(parent);
126|        }
127|        Ok(parents)
128|    }
129|
130|    fn verify_set(&mut self, set: &Set, parents: &[B::Handle]) -> Result<()> {
131|        ensure!(set.verified, "candidate incomplete; explicit reconciliation required");
132|        for (member, parent) in self.policy.host_members.iter().zip(parents) {
133|            let e = set.entries.iter().find(|e| e.member == member.member).context("missing member")?;
134|            ensure!(!e.deleting && !e.removed, "set is being retired");
135|            let expected = e.object.as_ref().context("unrecorded snapshot identity")?;
136|            let object = self.backend.child(parent, &e.name)?.context("owned snapshot missing")?;
137|            let actual = self.backend.inspect(&object)?;
138|            verify_snapshot(&actual, expected)?;
139|        }
140|        Ok(())
141|    }
142|
143|    pub fn prepare_host_set(&mut self) -> Result<SnapshotSetReceipt> {
144|        let mut state = self.state()?;
145|        ensure!(state.candidate.is_none() && state.retired.is_none(), "candidate or previous set must be reconciled first");
146|        let parents = self.parents(&state)?;
147|        if let Some(set) = &state.retained { self.verify_set(set, &parents)?; }
148|        let mut sources = Vec::new();
149|        for member in &self.policy.host_members {
150|            sources.push(self.backend.open_pin(&member.source, false)?);
151|        }
152|        let id = uuid::Uuid::new_v4().to_string();
153|        let set = Set { receipt_id: id.clone(), golden_source_uuid: String::new(), golden_received_uuid: String::new(), vector_references: Vec::new(), verified: false,
154|            entries: self.policy.host_members.iter().map(|m| Entry {
155|                member: m.member.clone(), name: format!("set-{id}"), object: None,
156|                deleting: false, removed: false,
157|            }).collect() };
158|        // Durably reserve the complete set before issuing any management ioctl.
159|        state.candidate = Some(set);
160|        self.journal.save(&state)?;
161|        for (i, (source, parent)) in sources.iter().zip(&parents).enumerate() {
162|            let member = &self.policy.host_members[i];
163|            let candidate = state.candidate.as_ref().unwrap();
164|            let name = &candidate.entries[i].name;
165|            ensure!(self.backend.child(parent, name)?.is_none(), "candidate name occupied");
166|            self.backend.snapshot(source, parent, name)?;
167|            let child = self.backend.child(parent, name)?.context("created candidate missing")?;
168|            let actual = self.backend.inspect(&child)?;
169|            ensure!(actual.readonly && actual.inode == 256 && actual.filesystem_uuid == member.source.filesystem_uuid
170|                && actual.parent_uuid == member.source.subvolume_uuid && actual.received_uuid == uuid::Uuid::nil().to_string(),
171|                "candidate snapshot postcondition mismatch; reserved state retained");
172|            state.candidate.as_mut().unwrap().entries[i].object = Some(SnapshotObject {
173|                member: member.member.clone(), filesystem_uuid: actual.filesystem_uuid,
174|                subvolume_id: actual.subvolume_id, subvolume_uuid: actual.uuid,
175|                parent_uuid: actual.parent_uuid,
176|                destination: format!("{}/{}", member.destination_parent.path, name),
177|            });
178|            self.journal.save(&state)?;
179|        }
180|        state.candidate.as_mut().unwrap().verified = true;
181|        self.verify_set(state.candidate.as_ref().unwrap(), &parents)?;
182|        self.journal.save(&state)?;
183|        receipt(state.candidate.as_ref().unwrap(), "candidate_verified")
184|    }
185|
186|    pub fn publish_host_set(&mut self, receipt_id: &str) -> Result<SnapshotSetReceipt> {
187|        let mut state = self.state()?;
188|        ensure!(state.retired.is_none(), "previous retirement outstanding");
189|        let candidate = state.candidate.as_ref().context("no candidate")?;
190|        ensure!(candidate.receipt_id == receipt_id, "receipt mismatch");
191|        let parents = self.parents(&state)?;
192|        self.verify_set(candidate, &parents)?;
193|        if let Some(set) = &state.retained { self.verify_set(set, &parents)?; }
194|        state.retired = state.retained.take();
195|        state.retained = state.candidate.take();
196|        self.journal.save(&state)?;
197|        receipt(state.retained.as_ref().unwrap(), "published")
198|    }
199|
200|    pub fn retire_previous_set(&mut self, published_receipt: &str) -> Result<SnapshotSetReceipt> {
201|        let mut state = self.state()?;
202|        let retained = state.retained.as_ref().context("no retained successor")?;
203|        ensure!(retained.receipt_id == published_receipt, "successor receipt mismatch");
204|        let parents = self.parents(&state)?;
205|        self.verify_set(retained, &parents)?;
206|        if state.retired.is_none() {
207|            return receipt(retained, "previous_retired");
208|        }
209|        for (i, parent) in parents.iter().enumerate() {
210|            let entry = &state.retired.as_ref().unwrap().entries[i];
211|            if entry.removed { continue; }
212|            let object = entry.object.as_ref().context("missing previous identity")?;
213|            let child = self.backend.child(parent, &entry.name)?;
214|            if let Some(child) = child {
215|                verify_snapshot(&self.backend.inspect(&child)?, object)?;
216|                let id = object.subvolume_id;
217|                // Record uncertain deletion before ioctl. Retry may accept absent
218|                // object only if this exact deletion was durably started.
219|                state.retired.as_mut().unwrap().entries[i].deleting = true;
220|                self.journal.save(&state)?;
221|                self.backend.delete_by_id(parent, id)?;
222|                ensure!(self.backend.child(parent, &state.retired.as_ref().unwrap().entries[i].name)?.is_none(), "deletion readback failed");
223|            } else {
224|                ensure!(entry.deleting, "previous snapshot disappeared outside mechanism");
225|            }
226|            state.retired.as_mut().unwrap().entries[i].removed = true;
227|            self.journal.save(&state)?;
228|        }
229|        state.retired = None;
230|        self.journal.save(&state)?;
231|        receipt(state.retained.as_ref().unwrap(), "previous_retired")
232|    }
233|
