53|pub struct Coordinator { policy: Policy, directory: File }
54|impl Coordinator {
55|    pub fn new(policy: Policy) -> Result<Self> {
56|        crate::objects::secure_ancestors("/var/lib/opdbus-storage")?;
57|        let directory = crate::objects::open_absolute("/var/lib/opdbus-storage")?;
58|        let mut this = Self { policy, directory }; this.load()?; Ok(this)
59|    }
60|    fn load(&mut self) -> Result<Journal> {
61|        let mut file = crate::objects::open_beneath(&self.directory, "captures.json", libc::O_RDONLY, 0)?;
62|        crate::objects::trusted_metadata(&file, false)?;
63|        ensure!(file.metadata()?.len() <= 524288, "capture journal oversized");
64|        let mut bytes = Vec::new(); file.read_to_end(&mut bytes)?;
65|        let journal: Journal = serde_json::from_slice(&bytes)?;
66|        ensure!(journal.version == 1, "capture journal not explicitly bootstrapped");
67|        ensure!(journal.scopes.keys().all(|id| self.policy.capture_scopes.iter().any(|s| &s.scope_id == id)), "unassigned journal scope");
68|        Ok(journal)
69|    }
70|    fn save(&mut self, journal: &Journal) -> Result<()> {
71|        let bytes = serde_json::to_vec(journal)?; ensure!(bytes.len() <= 524288, "capture journal oversized");
72|        let name = format!(".captures-{}", uuid::Uuid::new_v4());
73|        let mut file = crate::objects::open_beneath(&self.directory, &name, libc::O_WRONLY | libc::O_CREAT | libc::O_EXCL, 0o600)?;
74|        file.write_all(&bytes)?; file.sync_all()?;
75|        let name = std::ffi::CString::new(name)?;
76|        // SAFETY: generated leaf and constant target on the same held directory.
77|        ensure!(unsafe { libc::renameat(self.directory.as_raw_fd(), name.as_ptr(), self.directory.as_raw_fd(), c"captures.json".as_ptr()) } == 0,
78|            "capture journal publication: {}", std::io::Error::last_os_error());
79|        self.directory.sync_all()?; Ok(())
80|    }
81|    fn scope(&self, id: &str) -> Result<CaptureScope> {
82|        self.policy.capture_scopes.iter().find(|s| s.scope_id == id).cloned().context("capture scope not enrolled")
83|    }
84|    pub fn provision_vectors(&mut self) -> Result<Vec<ObjectPin>> {
85|        let policy = self.policy.vector_provision.clone().context("vector provisioning not explicitly enrolled")?;
86|        let mut journal = self.load()?;
87|        let base = parent(&policy.base)?;
88|        if let Some(provision) = &journal.provision {
89|            ensure!(!provision.pending, "partial vector provisioning requires explicit operator reconciliation");
90|            let pins = [&provision.timing, &provision.vectors, &provision.writer_lock].into_iter()
91|                .map(|p| p.clone().context("missing provisioned identity")).collect::<Result<Vec<_>>>()?;
92|            for pin in &pins {
93|                if pin.inode == 256 { crate::objects::pinned(pin, true)?; }
94|                else { open_lock(pin)?; }
95|            }
96|            return Ok(pins);
97|        }
98|        ensure!(crate::objects::list_names(&base)?.is_empty(), "vector base contains unowned/existing data; no initialization/adoption");
99|        journal.provision = Some(Provision { pending: true, timing: None, vectors: None, writer_lock: None });
100|        self.save(&journal)?;
101|        for name in ["timing", "vectors"] {
102|            btrfs_uapi::subvolume::subvolume_create(base.as_fd(), &std::ffi::CString::new(name)?, &[])?;
103|            btrfs_uapi::filesystem::sync(base.as_fd())?;
104|            let fd = crate::objects::open_beneath(&base, name, libc::O_RDONLY | libc::O_DIRECTORY, 0)?;
105|            let pin = pin_for(&fd, format!("{}/{}", policy.base.path, name))?;
106|            ensure!(pin.filesystem_uuid == crate::policy::HOST_FS && pin.inode == 256, "provisioned member readback failed");
107|            if name == "timing" { journal.provision.as_mut().unwrap().timing = Some(pin); }
108|            else { journal.provision.as_mut().unwrap().vectors = Some(pin); }
109|            self.save(&journal)?;
110|        }
111|        let lock = crate::objects::open_beneath(&base, ".writer.lock", libc::O_RDWR | libc::O_CREAT | libc::O_EXCL, 0o600)?;
112|        lock.sync_all()?; base.sync_all()?;
113|        let pin = pin_for(&lock, format!("{}/.writer.lock", policy.base.path))?;
114|        journal.provision.as_mut().unwrap().writer_lock = Some(pin);
115|        journal.provision.as_mut().unwrap().pending = false;
116|        self.save(&journal)?;
117|        self.provision_vectors()
118|    }
119|
120|    pub fn capture(&mut self, request: &CaptureRequest) -> Result<CaptureReceipt> {
121|        self.capture_internal(request, false)
122|    }
123|    fn capture_internal(&mut self, request: &CaptureRequest, recover: bool) -> Result<CaptureReceipt> {
124|        let scope = self.scope(&request.scope_id)?;
125|        ensure!(scope.workflow == request.workflow && !uuid::Uuid::parse_str(&request.capture_id)?.is_nil(), "capture workflow/ID mismatch");
126|        let initial = self.load()?;
127|        if initial.scopes.get(&scope.scope_id).is_some_and(|s| s.retiring.is_some() && s.candidate.is_none()) {
128|            self.reconcile_retention(&scope.scope_id)?;
129|        }
130|        let mut journal = self.load()?;
131|        let state = journal.scopes.entry(scope.scope_id.clone()).or_default();
132|        ensure!(state.retiring.is_none(), "capture retirement outstanding");
133|        if recover {
134|            let pending = state.candidate.as_ref().context("recovery candidate missing")?;
135|            ensure!(state.retained.is_none() && pending.capture_id == request.capture_id
136|                && pending.origin == request.origin && pending.members.is_empty()
137|                && !pending.verified && !pending.transferred && pending.parent_capture_id.is_empty(),
138|                "recovery is not the exact initial reserved capture stage");
139|        } else { ensure!(state.candidate.is_none(), "capture candidate outstanding"); }
140|        let source_parent = parent(&scope.snapshot_parent)?;
141|        let receive_parent = scope.receive_parent.as_ref().map(parent).transpose()?;
142|        check_generations(&source_parent, state)?;
143|        if let Some(fd) = &receive_parent { check_generations(fd, state)?; }
144|        let old = state.retained.clone();
145|        if let Some(retained) = &old {
146|            if retained.capture_id == request.capture_id {
147|                ensure!(retained.origin == request.origin, "capture ID belongs to another admitted origin");
148|                verify_generation(&scope, retained, &source_parent, receive_parent.as_ref())?;
149|                return receipt(&scope, retained, false);
150|            }
151|        }
152|        if let Some(old) = &old { verify_generation(&scope, old, &source_parent, receive_parent.as_ref())?; }
153|        let mut sources = Vec::new();
154|        for member in &scope.members {
155|            let source = crate::objects::pinned(&member.source, false)?;
156|            let info = btrfs_uapi::subvolume::subvolume_info(source.as_fd())?;
157|            ensure!(!btrfs_uapi::subvolume::subvolume_list(source.as_fd())?.iter().any(|s| s.parent_id == info.id),
158|                "capture source has un-enrolled nested subvolumes");
159|            sources.push(source);
160|        }
161|        // Broker owns its OWN lock descriptor. A cancelled client cannot unlock
162|        // this open-file description by dropping or unlocking its own flock.
163|        let lock = scope.writer_lock.as_ref().map(open_lock).transpose()?;
164|        if let Some(fd) = &lock {
165|            ensure!(unsafe { libc::flock(fd.as_raw_fd(), libc::LOCK_EX) } == 0, "capture writer lock unavailable");
166|        }
