{"content":"1|use super::engine::*;
2|use crate::policy::*;
3|use anyhow::{Result, bail, ensure};
4|use std::collections::BTreeMap;
5|use std::sync::{Arc, Mutex};
6|
7|#[derive(Default)]
8|struct Data {
9|    objects: BTreeMap<String, ObjectIdentity>,
10|    effects: usize,
11|    fail_at: Option<usize>,
12|}
13|struct MockBackend(Arc<Mutex<Data>>);
14|impl Backend for MockBackend {
15|    type Handle = String;
16|    fn open_pin(&mut self, pin: &ObjectPin, _secure: bool) -> Result<String> {
17|        let d = self.0.lock().unwrap();
18|        let i = d.objects.get(&pin.path).ok_or_else(|| anyhow::anyhow!("missing pin"))?;
19|        ensure!(i.filesystem_uuid == pin.filesystem_uuid && i.subvolume_id == pin.subvolume_id
20|            && i.uuid == pin.subvolume_uuid && i.inode == pin.inode, "pin mismatch");
21|        Ok(pin.path.clone())
22|    }
23|    fn inspect(&mut self, handle: &String) -> Result<ObjectIdentity> {
24|        self.0.lock().unwrap().objects.get(handle).cloned().ok_or_else(|| anyhow::anyhow!("missing object"))
25|    }
26|    fn names(&mut self, parent: &String) -> Result<Vec<String>> {
