255|impl NativeBackend {
256|    pub fn new(policy: &Policy) -> Result<Self> {
257|        let capture = if !policy.capture_scopes.is_empty() || policy.vector_provision.is_some() { Some(crate::capture::Coordinator::new(policy.clone())?) } else { None };
258|        Ok(Self { capture })
259|    }
