261|impl Backend for NativeBackend {
262|    fn reconcile_queued_capture_retirements(&mut self) -> Result<()> {
263|        if let Some(capture) = &mut self.capture { capture.reconcile_queued_retirements()?; }
264|        Ok(())
265|    }
266|    fn capture_references(&mut self) -> Result<Vec<crate::protocol::CaptureReference>> {
267|        self.capture.as_mut().map(|c| c.current_references()).transpose().map(|v| v.unwrap_or_default())
268|    }
269|    fn verify_capture_references(&mut self, refs: &[crate::protocol::CaptureReference]) -> Result<()> {
270|        if refs.is_empty() { return Ok(()); }
271|        self.capture.as_mut().context("capture reference backend missing")?.verify_references(refs)
272|    }
273|    type Handle = std::fs::File;
274|    fn open_pin(&mut self, pin: &ObjectPin, secure: bool) -> Result<Self::Handle> {
275|        if secure { crate::objects::secure_ancestors(&pin.path)?; }
276|        crate::objects::pinned(pin, secure)
277|    }
278|    fn inspect(&mut self, handle: &Self::Handle) -> Result<ObjectIdentity> {
279|        use std::os::fd::AsFd;
280|        use std::os::unix::fs::MetadataExt;
281|        let fs = btrfs_uapi::filesystem::filesystem_info(handle.as_fd())?;
282|        let s = btrfs_uapi::subvolume::subvolume_info(handle.as_fd())?;
283|        Ok(ObjectIdentity { filesystem_uuid: fs.uuid.to_string(), subvolume_id: s.id,
284|            uuid: s.uuid.to_string(), parent_uuid: s.parent_uuid.to_string(), received_uuid: s.received_uuid.to_string(),
285|            readonly: crate::objects::readonly(handle)?, inode: handle.metadata()?.ino() })
286|    }
287|    fn names(&mut self, parent: &Self::Handle) -> Result<Vec<String>> { crate::objects::list_names(parent) }
288|    fn child(&mut self, parent: &Self::Handle, name: &str) -> Result<Option<Self::Handle>> {
289|        // Distinguish ENOENT from every other openat2 failure; no exists()/reopen.
290|        match crate::objects::open_beneath(parent, name, libc::O_RDONLY | libc::O_DIRECTORY, 0) {
291|            Ok(file) => Ok(Some(file)),
292|            Err(error) if error.downcast_ref::<std::io::Error>().is_some_and(|e| e.raw_os_error() == Some(libc::ENOENT)) => Ok(None),
293|            Err(error) => Err(error),
294|        }
295|    }
296|    fn snapshot(&mut self, source: &Self::Handle, parent: &Self::Handle, name: &str) -> Result<()> {
297|        use std::os::fd::AsFd;
298|        btrfs_uapi::subvolume::snapshot_create(parent.as_fd(), source.as_fd(), &std::ffi::CString::new(name)?, true, &[])?;
299|        btrfs_uapi::filesystem::sync(parent.as_fd())?;
300|        Ok(())
301|    }
302|    fn delete_by_id(&mut self, parent: &Self::Handle, id: u64) -> Result<()> {
303|        use std::os::fd::AsFd;
304|        // Kernel selects the already-validated subvolume ID, not a raceable name.
305|        btrfs_uapi::subvolume::subvolume_delete_by_id(parent.as_fd(), id)?;
306|        btrfs_uapi::filesystem::sync(parent.as_fd())?;
307|        Ok(())
308|    }
