{"content":"1|use std::sync::Arc;
2|use tokio::sync::Mutex;
3|use zbus::message::Header;
4|use crate::authorization:*** authorize};
5|use crate::engine::{Engine, NativeBackend};
6|use crate::journal::StateDirectory;
7|use crate::protocol::{OriginContext, SnapshotSetReceipt};
8|
9|type NativeEngine = Engine<NativeBackend, StateDirectory>;
10|#[derive(Clone)]
11|pub struct StorageService { connection: zbus::Connection, engine: Arc<Mutex<NativeEngine>>, operator_uid: u32 }
12|impl StorageService {
13|    async fn run_scoped<T: Send + 'static>(
14|        &self, header: Header<'_>, method: String, scope_id: String, origin: OriginContext,
15|        f: impl FnOnce(&mut NativeEngine) -> anyhow::Result<T> + Send + 'static,
16|    ) -> zbus::fdo::Result<T> {
17|        let sender = header.sender().ok_or_else(|| zbus::fdo::Error::AccessDenied("sender absent".into()))?.to_string();
18|        let mut guard = self.engine.clone().lock_owned().await;
19|        let current = crate::journal::load_policy().map_err(|e| zbus::fdo::Error::AccessDenied(e.to_string()))?;
20|        crate::admission::verify_object_policy(guard.policy(), &current).map_err(|e| zbus::fdo::Error::AccessDenied(e.to_string()))?;
21|        let admission = current.admission.as_ref().ok_or_else(|| zbus::fdo::Error::AccessDenied("admission service not enrolled".into()))?;
22|        crate::admission::authorize_delegated_scope_with(&self.connection, &sender, admission, &method, &scope_id, &origin, crate::admission::read_process).await
23|            .map_err(|e| zbus::fdo::Error::AccessDenied(e.to_string()))?;
24|        let reloaded = crate::journal::load_policy().map_err(|e| zbus::fdo::Error::AccessDenied(e.to_string()))?;
25|        crate::admission::verify_object_policy(guard.policy(), &reloaded).map_err(|e| zbus::fdo::Error::AccessDenied(e.to_string()))?;
26|        if current.admission != reloaded.admission { return Err(zbus::fdo::Error::AccessDenied("admission policy changed during authorization".into())); }
27|        tokio::task::spawn_blocking(move || f(&mut guard)).await
28|            .map_err(|e| { eprintln!("op-storage backend failure: {e:#}"); zbus::fdo::Error::Failed(format!("{e:#}")) })?.map_err(|e| { eprintln!("op-storage backend failure: {e:#}"); zbus::fdo::Error::Failed(format!("{e:#}")) })
29|    }
30|    pub fn new(connection: zbus::Connection, engine: NativeEngine) -> Self {
31|        let operator_uid = engine.policy().operator_uid;
32|        Self { connection, engine: Arc::new(Mutex::new(engine)), operator_uid }
33|    }
34|    async fn run<T: Send + 'static>(
35|        &self, header: Header<'_>, operation: Operation,
36|        f: impl FnOnce(&mut NativeEngine) -> anyhow::Result<T> + Send + 'static,
37|    ) -> zbus::fdo::Result<T> {
38|        let sender = header.sender().ok_or_else(|| zbus::fdo::Error::AccessDenied("sender absent".into()))?.to_string();
39|        // Serialize policy/count/state/FS effects, including authorization. Flock
40|        // held by journal additionally excludes a second daemon process.
41|        let mut guard = self.engine.clone().lock_owned().await;
42|        let current = crate::journal::load_policy().map_err(|e| zbus::fdo::Error::AccessDenied(e.to_string()))?;
43|        crate::admission::verify_object_policy(guard.policy(), &current).map_err(|e| zbus::fdo::Error::AccessDenied(e.to_string()))?;
44|        authorize(&self.connection, &sender, operation, self.operator_uid).await
45|            .map_err(|e| zbus::fdo::Error::AccessDenied(e.to_string()))?;
46|        tokio::task::spawn_blocking(move || f(&mut guard)).await
47|            .map_err(|e| { eprintln!("op-storage backend failure: {e:#}"); zbus::fdo::Error::Failed(format!("{e:#}")) })?
48|            .map_err(|e| { eprintln!("op-storage backend failure: {e:#}"); zbus::fdo::Error::Failed(format!("{e:#}")) })
49|    }
50|}
51|#[zbus::interface(name = "org.opdbus.Storage1")]
52|impl StorageService {
53|    async fn prepare_host_snapshot_set(&self, #[zbus(header)] header: Header<'_>) -> zbus::fdo::Result<(SnapshotSetReceipt,)> {
54|        self.run(header, Operation::PrepareHost, |e| e.prepare_host_set()).await.map(|receipt| (receipt,))
55|    }
56|    async fn publish_host_snapshot_set(&self, receipt_id: String, #[zbus(header)] header: Header<'_>) -> zbus::fdo::Result<(SnapshotSetReceipt,)> {
57|        self.run(header, Operation::PublishHost, move |e| e.publish_host_set(&receipt_id)).await.map(|receipt| (receipt,))
58|    }
59|    async fn retire_previous_host_snapshot_set(&self, published_receipt: String, #[zbus(header)] header: Header<'_>) -> zbus::fdo::Result<(SnapshotSetReceipt,)> {
60|        self.run(header, Operation::RetireHost, move |e| e.retire_previous_set(&published_receipt)).await.map(|receipt| (receipt,))
61|    }
62|    async fn delegated_host_snapshot_set(&self, method: String, receipt_id: String, origin: OriginContext,
63|        #[zbus(header)] header: Header<'_>) -> zbus::fdo::Result<(SnapshotSetReceipt,)> {
64|        let sender = header.sender().ok_or_else(|| zbus::fdo::Error::AccessDenied("sender absent".into()))?.to_string();
65|        let mut guard = self.engine.clone().lock_owned().await;
